module Sdpram (
  input  wire          io_read_clk,
  input  wire          io_read_Valid,
  input  wire [19:0]   io_read_Address,
  output wire [255:0]  io_read_Data,
  input  wire          io_write_clk,
  input  wire [31:0]   io_write_Wen,
  input  wire          io_write_Valid,
  input  wire [19:0]   io_write_Address,
  input  wire [255:0]  io_write_Data,
  input  wire          clk,
  input  wire          reset
);

  reg        [255:0]  mem_spinal_port0;
  reg [255:0] mem [0:1048575];

  always @(posedge clk) begin
    if(io_read_Valid) begin
      mem_spinal_port0 <= mem[io_read_Address];
    end
  end

  always @(posedge clk) begin
    if(io_write_Valid) begin
      mem[io_write_Address] <= io_write_Data;
    end
  end

  assign io_read_Data = mem_spinal_port0;

endmodule

