module SIntShifter (
  input  wire [23:0]   io_input,
  input  wire [5:0]    io_shiftAmount,
  output wire [23:0]   io_output
);

  wire       [5:0]    _zz_effShift;
  wire       [110:0]  _zz_rawResult;
  wire       [47:0]   _zz_rawResult_1;
  wire       [110:0]  _zz_rawResult_2;
  wire       [5:0]    _zz_rawResult_3;
  wire       [110:0]  _zz_satResult;
  wire       [110:0]  _zz_satResult_1;
  wire       [110:0]  _zz_satResult_2;
  wire       [110:0]  _zz_satResult_3;
  wire       [110:0]  _zz_satResult_4;
  wire       [5:0]    effShift;
  wire       [47:0]   extInput;
  wire       [110:0]  rawResult;
  wire       [47:0]   maxS;
  wire       [47:0]   minS;
  wire       [110:0]  satResult;

  assign _zz_effShift = (($signed(io_shiftAmount) < $signed(6'h28)) ? 6'h28 : io_shiftAmount);
  assign _zz_rawResult_1 = ($signed(extInput) >>> effShift);
  assign _zz_rawResult = {{63{_zz_rawResult_1[47]}}, _zz_rawResult_1};
  assign _zz_rawResult_2 = ({{63{extInput[47]}},extInput} <<< _zz_rawResult_3);
  assign _zz_rawResult_3 = (- effShift);
  assign _zz_satResult = {{63{maxS[47]}}, maxS};
  assign _zz_satResult_1 = {{63{maxS[47]}}, maxS};
  assign _zz_satResult_2 = (($signed(rawResult) < $signed(_zz_satResult_3)) ? _zz_satResult_4 : rawResult);
  assign _zz_satResult_3 = {{63{minS[47]}}, minS};
  assign _zz_satResult_4 = {{63{minS[47]}}, minS};
  assign effShift = (($signed(6'h18) < $signed(io_shiftAmount)) ? 6'h18 : _zz_effShift);
  assign extInput = {{24{io_input[23]}}, io_input};
  assign rawResult = (($signed(6'h0) < $signed(effShift)) ? _zz_rawResult : _zz_rawResult_2);
  assign maxS = 48'h0000007fffff;
  assign minS = 48'hffffff800000;
  assign satResult = (($signed(_zz_satResult) < $signed(rawResult)) ? _zz_satResult_1 : _zz_satResult_2);
  assign io_output = satResult[23:0];

endmodule

